<?php
/** TEMP PS S1688 md — DEPLOY: (1) mu-plugins/petshop-relaunch.php v1.0.1 → v1.1.0 (visas failas iš base64; md5 sargas 9e956278…; bak uploads/ps-backups/petshop-relaunch.php.bak_s1688; token_get_all; heartbeat, rollback); (2) petshop-pakartoti.php grupe() fallback be užsakymo (str_replace, md5 sargas 33d4756e…, bak .bak_s1688). Fazė tikrinti — atskira užklausa. */
add_action('init', function(){
  if (!isset($_GET['ps_s1688md'])) return; $o=array('v'=>'S1688 md'); $f=$_GET['ps_s1688md'];
  $bak=wp_upload_dir()['basedir'].'/ps-backups'; wp_mkdir_p($bak);
  $rl=WPMU_PLUGIN_DIR.'/petshop-relaunch.php'; $pk=WPMU_PLUGIN_DIR.'/petshop-pakartoti.php';
  $tok_ok=function($code){ try { token_get_all($code, TOKEN_PARSE); return true; } catch (Throwable $e) { return $e->getMessage(); } };
  $heart=function(){ $r=wp_remote_get(home_url('/?ps_hb='.time()),array('timeout'=>25,'sslverify'=>false)); return is_wp_error($r)?0:wp_remote_retrieve_response_code($r); };
  if($f==='deploy'){
    // 1) relaunch
    $o['rl_md5_pries']=md5_file($rl);
    if(substr($o['rl_md5_pries'],0,8)!=='9e956278'){ $o['stop']='relaunch md5 nesutampa'; }
    else { $new=base64_decode(''); $t=$tok_ok($new); if($t!==true){ $o['stop']='relaunch token: '.$t; }
      else { copy($rl,$bak.'/petshop-relaunch.php.bak_s1688'); file_put_contents($rl,$new); $o['rl_md5_po']=md5_file($rl); $hb=$heart(); $o['rl_hb']=$hb; if($hb>=500||$hb===0){ copy($bak.'/petshop-relaunch.php.bak_s1688',$rl); $o['rl_rollback']=md5_file($rl); $o['stop']='relaunch heartbeat '.$hb; } } }
    if(empty($o['stop'])){
      // 2) pakartoti
      $o['pk_md5_pries']=md5_file($pk); $s=file_get_contents($pk);
      $a="\$oid = (int) \$r['last_order_id']; \$o = wc_get_order( \$oid ); if ( ! \$o ) return null;";
      $b="\$oid = (int) \$r['last_order_id']; \$o = wc_get_order( \$oid ); if ( ! \$o ) return self::grupe_preke( \$uid, \$pid, \$r );";
      $c="	public static function grupe( \$uid, \$pid ) {";
      $d="	/** S1688: sekimas be WC užsakymo (relaunch priminimas iš prekės puslapio) — grupė iš vienos prekės ×1, kasa = add-to-cart. */
	public static function grupe_preke( \$uid, \$pid, \$r ) {
		\$pr = wc_get_product( \$pid ); \$prekes = array(); \$nera = array(); \$suma = 0.0;
		if ( ! \$pr || 'publish' !== \$pr->get_status() || ! \$pr->is_purchasable() || ! \$pr->is_in_stock() ) { \$nera[] = \$pr ? \$pr->get_name() : ( 'Prekė #' . \$pid ); }
		else { \$suma = (float) wc_get_price_to_display( \$pr ); \$prekes[] = array( 'pid' => \$pid, 'item_id' => 0, 'pav' => \$pr->get_name(), 'kiekis' => 1, 'kaina' => \$suma, 'url' => \$pr->get_permalink(), 'rinkinys' => false ); }
		\$ts = strtotime( (string) \$r['predicted_empty_date'] );
		\$men = array( 1 => 'sausio', 'vasario', 'kovo', 'balandžio', 'gegužės', 'birželio', 'liepos', 'rugpjūčio', 'rugsėjo', 'spalio', 'lapkričio', 'gruodžio' );
		return array( 'order_id' => 0, 'prekes' => \$prekes, 'nera' => \$nera, 'suma' => \$suma, 'data' => \$ts ? \$men[ (int) date( 'n', \$ts ) ] . ' ' . (int) date( 'j', \$ts ) . ' d.' : '', 'kasa' => add_query_arg( array( 'add-to-cart' => \$pid, 'quantity' => 1 ), wc_get_checkout_url() ) );
	}

	public static function grupe( \$uid, \$pid ) {";
      $o['pk_a_n']=substr_count($s,$a); $o['pk_c_n']=substr_count($s,$c);
      if(substr($o['pk_md5_pries'],0,8)!=='33d4756e'||$o['pk_a_n']!==1||$o['pk_c_n']!==1){ $o['stop']='pakartoti sargas'; }
      else { $n=str_replace($a,$b,$s); $n=str_replace($c,$d,$n); $n=str_replace('Version: 1.1.5','Version: 1.1.6',$n); $t=$tok_ok($n); if($t!==true){ $o['stop']='pakartoti token: '.$t; }
        else { copy($pk,$bak.'/petshop-pakartoti.php.bak_s1688'); file_put_contents($pk,$n); $o['pk_md5_po']=md5_file($pk); $hb=$heart(); $o['pk_hb']=$hb; if($hb>=500||$hb===0){ copy($bak.'/petshop-pakartoti.php.bak_s1688',$pk); $o['pk_rollback']=md5_file($pk); $o['stop']='pakartoti heartbeat '.$hb; } } }
    }
  } else {
    $o['rl_md5']=md5_file($rl); $o['pk_md5']=md5_file($pk); $o['rl_ver']=get_file_data($rl,array('v'=>'Version'))['v']; $o['pk_ver']=get_file_data($pk,array('v'=>'Version'))['v'];
    $o['metodai']=array('registruoti'=>method_exists('Petshop_Relaunch','registruoti'),'rest_priminti'=>method_exists('Petshop_Relaunch','rest_priminti'),'grupe_preke'=>method_exists('Petshop_Pakartoti','grupe_preke'));
    $o['rest']=isset(rest_get_server()->get_routes()['/ps-relaunch/v1/priminti']); global $wpdb; $o['cols']=$wpdb->get_col("SHOW COLUMNS FROM ".Petshop_Relaunch::t()); $o['v11']=get_option('ps_relaunch_lentele_v11');
    $o['dienos_12466_20']=Petshop_Relaunch::dienos(12466,20,'dog'); $o['rusis_12466']=Petshop_Relaunch::rusis(12466);
    $o['grupe_preke_test']=Petshop_Pakartoti::grupe_preke(44,12466,array('predicted_empty_date'=>'2026-11-01'));
